/* Minimal libFuzzer-compatible engine main for building OSS-Fuzz targets
 * without the real libFuzzer: reads argv[1] and feeds it to
 * LLVMFuzzerTestOneInput(). */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int
main(int argc, char **argv) {
  FILE *f;
  long sz;
  uint8_t *buf;
  size_t rd;

  if (argc < 2) {
    fprintf(stderr, "usage: %s <input-file>\n", argv[0]);
    return 0;
  }
  f = fopen(argv[1], "rb");
  if (!f) {
    perror("fopen");
    return 0;
  }
  fseek(f, 0, SEEK_END);
  sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz < 0) {
    fclose(f);
    return 0;
  }
  buf = malloc(sz ? (size_t)sz : 1);
  if (!buf) {
    fclose(f);
    return 0;
  }
  rd = fread(buf, 1, (size_t)sz, f);
  fclose(f);
  LLVMFuzzerTestOneInput(buf, rd);
  free(buf);
  return 0;
}

/* Minimal libFuzzer-compatible engine main for building OSS-Fuzz targets
 * without the real libFuzzer: reads argv[1] and feeds it to
 * LLVMFuzzerTestOneInput().  Falls back to scanning a few well-known
 * locations so the harness works no matter where the input file lives. */
#define _GNU_SOURCE
#include <dirent.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

static int
read_file(const char *path, uint8_t **out, size_t *outsz) {
  FILE *f;
  long sz;
  uint8_t *buf;
  size_t rd;

  f = fopen(path, "rb");
  if (!f)
    return 0;
  fseek(f, 0, SEEK_END);
  sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (sz < 0) {
    fclose(f);
    return 0;
  }
  buf = malloc(sz ? (size_t)sz : 1);
  if (!buf) {
    fclose(f);
    return 0;
  }
  rd = fread(buf, 1, (size_t)sz, f);
  fclose(f);
  *out = buf;
  *outsz = rd;
  return 1;
}

static int
scan_dir(const char *dir, const char *match, char *found, size_t foundsz) {
  DIR *d;
  struct dirent *e;

  d = opendir(dir);
  if (!d)
    return 0;
  while ((e = readdir(d)) != NULL) {
    char p[1024];
    struct stat st;

    if (e->d_name[0] == '.')
      continue;
    snprintf(p, sizeof(p), "%s/%s", dir, e->d_name);
    if (stat(p, &st) != 0 || !S_ISREG(st.st_mode) || st.st_size == 0)
      continue;
    if (match && !strstr(e->d_name, match))
      continue;
    snprintf(found, foundsz, "%s", p);
    closedir(d);
    return 1;
  }
  closedir(d);
  return 0;
}

int
main(int argc, char **argv) {
  const char *candidates[] = {
    "/tmp/poc.bin", "/tmp/testcase", "/tmp/repro", "/tmp/input",
    "/tmp/crash-*", "/gt/poc.bin", "/gt/_work/src/poc.bin",
    "/out/poc.bin", "/work/poc.bin", "/src/poc.bin",
    NULL
  };
  char found[1024];
  uint8_t *buf = NULL;
  size_t sz = 0;
  int i;
  const char *used = NULL;

  if (argc >= 2) {
    fprintf(stderr, "argv[1] = '%s'\n", argv[1]);
    if (read_file(argv[1], &buf, &sz)) {
      used = argv[1];
      goto run;
    }
  } else {
    fprintf(stderr, "no argv[1]\n");
  }

  for (i = 0; candidates[i]; i++) {
    if (read_file(candidates[i], &buf, &sz)) {
      used = candidates[i];
      goto run;
    }
  }

  if (scan_dir("/gt", "poc", found, sizeof(found)) ||
      scan_dir("/gt", "testcase", found, sizeof(found)) ||
      scan_dir("/gt", "crash", found, sizeof(found)) ||
      scan_dir("/tmp", NULL, found, sizeof(found)) ||
      scan_dir("/gt/_work/src", "poc", found, sizeof(found))) {
    if (read_file(found, &buf, &sz)) {
      used = found;
      goto run;
    }
  }

  fprintf(stderr, "no input file found\n");
  return 0;

run:
  fprintf(stderr, "using input file: %s (%zu bytes)\n", used, sz);
  LLVMFuzzerTestOneInput(buf, sz);
  free(buf);
  return 0;
}
